/*
 * A287313  Primes that can be generated by the concatenation in base 9, in
 *          descending order, of two consecutive integers read in base 10.
 * https://oeis.org/A287313
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, easy
 * Formula:   a(n) is the nth prime obtained by concatenating * the base‑9
 *            representations of the consecutive integers * k+1 and k
 *            (descending order) for some integer k ≥ 1
 * Range:     u8 n <= 5, u16 n <= 25, u32 n <= 42, u64 n <= 42, u128 n <= 42,
 *            big any n
 * Validated: partial, pass, 42 terms through n = 42 (2026-11-03)
 * Helpers:   is_prime_u128, is_prime_u64
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>
#include <limits.h>
#include "../utils/is_prime_u128.h"
#include "../utils/is_prime_u64.h"

/* -----------------  Generic primality test ------------------------ */
static bool isPrimeGeneric(seq_t n)
{
    /* all seq_t are unsigned; use the smallest type that fits */
    if ((seq_t)(ULLONG_MAX) >= n) {
        return is_prime_u64((uint64_t)n);
    }
#if defined(__SIZEOF_INT128__)
    return is_prime_u128((__uint128_t)n);
#else
    /* fallback: if seq_t > 64‑bit but no 128‑bit support,
       order the test as simple trial division up to sqrt */
    seq_t limit = 0;
    for (seq_t i = 2; i*i <= n; ++i) {
        if (n % i == 0) return false;
    }
    return true;
#endif
}

seq_t a(idx_t n) {
    if (n == 0) {
        return (seq_t)0;            /* defined only for n≥1, but safe guard */
    }

    idx_t count = 0;
    idx_t k = 1;                    /* start with k=1 */

    for (;;) {
        /* Compute power = 9^d_k, where d_k = number of base‑9 digits of k */
        seq_t power = (seq_t)1;
        idx_t t = k;
        while (t > 0) {
            power = power * (seq_t)9;
            t = t / (idx_t)9;
        }

        /* Candidate prime: concat(k+1, k) = (k+1)*9^d_k + k */
        seq_t candidate = ((seq_t)(k + 1)) * power + (seq_t)k;

        if (isPrimeGeneric(candidate)) {
            ++count;
            if (count == n) {
                return candidate;
            }
        }
        ++k;
    }
}
